"""Clean a PostgreSQL schema dump so it is stable and loadable without psql."""

import re


def clean_schema(sql: str) -> str:
    # psql meta commands: \restrict, \unrestrict, \connect, ...
    sql = re.sub(r"(?m)^\\.*$\n?", "", sql)
    # Comments generated by pg_dump.
    sql = re.sub(r"(?m)^--.*$\n?", "", sql)
    # Session settings and SELECT pg_catalog.set_config(...).
    sql = re.sub(r"(?ims)^SET\s+.*?;\s*", "", sql)
    sql = re.sub(r"(?ims)^SELECT\s+pg_catalog\.set_config\(.*?;\s*", "", sql)
    sql = re.sub(
        r"(?ims)^CREATE\s+SCHEMA\s+(?:IF\s+NOT\s+EXISTS\s+)?public\s*;\s*", "", sql
    )
    # Ownership, grants and revocations depend on the machine, not the schema.
    sql = re.sub(
        r"(?ims)^ALTER\s+(?:TABLE|SCHEMA|SEQUENCE|VIEW|FUNCTION|TYPE)"
        r".*?\s+OWNER\s+TO\s+.*?;\s*",
        "",
        sql,
    )
    sql = re.sub(r"(?ims)^(?:GRANT|REVOKE)\s+.*?;\s*", "", sql)
    # Extension descriptions need extension ownership to replay. Table and column
    # comments are business documentation written in migrations, so they stay.
    sql = re.sub(r"(?ims)^COMMENT\s+ON\s+EXTENSION\s+.*?;\s*", "", sql)
    sql = re.sub(r"\n{3,}", "\n\n", sql)
    sql = re.sub(r"\bpublic\.", "", sql)
    return sql.strip() + "\n"
